import 'dart:async';import 'dart:math';import 'package:flutter/material.dart';void main()=>runApp(MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData.dark().copyWith(scaffoldBackgroundColor:Color(0xFF0A0E14)),home:Main()));
class Main extends StatefulWidget{Main({super.key});@override State<Main> createState()=>_M();}
class _M extends State<Main>{int i=0;List<double> p=List.generate(50,(i)=>22000+Random().nextDouble()*300-150);late Timer t;@override void initState(){super.initState();t=Timer.periodic(Duration(seconds:1),(_){setState((){p.removeAt(0);p.add(p.last+Random().nextDouble()*20-10);});});}@override void dispose(){t.cancel();super.dispose();}@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(backgroundColor:Color(0xFF151A26),title:Row(children:[Container(padding:EdgeInsets.all(6),decoration:BoxDecoration(color:Color(0xFF00FF88),borderRadius:BorderRadius.circular(6)),child:Icon(Icons.visibility,color:Colors.black,size:18)),SizedBox(width:10),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('TRADING EYE',style:TextStyle(fontSize:16,fontWeight:FontWeight.bold)),Text('LIVE',style:TextStyle(fontSize:10,color:Color(0xFF00FF88)))])])),body:i==0?ListView(children:[for(var s in [{'n':'RELIANCE','p':2845,'c':2.4,'s':'STRONG BUY'},{'n':'TCS','p':3912,'c':1.8,'s':'BUY'},{'n':'INFY','p':1545,'c':3.1,'s':'BREAKOUT'},{'n':'NIFTY','p':22150,'c':0.8,'s':'BULLISH'},{'n':'BANKNIFTY','p':48200,'c':1.2,'s':'BUY'}]) Container(margin:EdgeInsets.fromLTRB(12,8,12,0),padding:EdgeInsets.all(14),decoration:BoxDecoration(color:Color(0xFF151A26),borderRadius:BorderRadius.circular(12)),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(s['n'].toString(),style:TextStyle(fontWeight:FontWeight.bold)),Text('₹ ${s['p']}',style:TextStyle(color:Colors.white70))])),Column(children:[Container(padding:EdgeInsets.symmetric(horizontal:8,vertical:3),decoration:BoxDecoration(color:Colors.green.withOpacity(0.2),borderRadius:BorderRadius.circular(6)),child:Text(s['s'].toString(),style:TextStyle(color:Colors.green,fontSize:11,fontWeight:FontWeight.bold))),Text('${s['c']}%',style:TextStyle(color:Colors.green))])]))]):i==1?Padding(padding:EdgeInsets.all(16),child:Column(children:[Text('₹ ${p.last.toStringAsFixed(1)}',style:TextStyle(fontSize:26,fontWeight:FontWeight.bold,color:Color(0xFF00FF88))),SizedBox(height:12),Expanded(child:Container(padding:EdgeInsets.all(10),decoration:BoxDecoration(color:Color(0xFF151A26),borderRadius:BorderRadius.circular(16)),child:CustomPaint(size:Size.infinite,painter:CP(p))))])):Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.auto_graph,size:60,color:Color(0xFF00FF88)),SizedBox(height:10),Text('TRADING EYE v1.0'),Text('Made by Ronit',style:TextStyle(color:Colors.grey))])),bottomNavigationBar:BottomNavigationBar(backgroundColor:Color(0xFF151A26),selectedItemColor:Color(0xFF00FF88),currentIndex:i,onTap:(x)=>setState(()=>i=x),items:[BottomNavigationBarItem(icon:Icon(Icons.radar),label:'SCANNER'),BottomNavigationBarItem(icon:Icon(Icons.show_chart),label:'CHART'),BottomNavigationBarItem(icon:Icon(Icons.person),label:'ME')]),);}}
class CP extends CustomPainter{List<double> d;CP(this.d);@override void paint(Canvas c,Size s){if(d.isEmpty) return;double mn=d.reduce(min),mx=d.reduce(max),r=mx-mn;Paint pt=Paint()..color=Color(0xFF00FF88)..strokeWidth=2..style=PaintingStyle.stroke;Path ph=Path();for(int j=0;j<d.length;j++){double x=j/(d.length-1)*s.width,y=s.height-((d[j]-mn)/(r==0?1:r))*s.height;if(j==0)ph.moveTo(x,y);else ph.lineTo(x,y);}c.drawPath(ph,pt);} @override bool shouldRepaint(old)=>true;}
